#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// P problem: Binary Search - solvable in O(log n)
bool binarySearch(vector<int>& arr, int target) {
    int left = 0, right = arr.size() - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] == target) return true;
        else if (arr[mid] < target) left = mid + 1;
        else right = mid - 1;
    }
    return false;
}

// NP problem: Subset Sum - verify in O(n), solve in O(2^n)
bool verifySubsetSum(vector<int>& arr, vector<int>& subset, int target) {
    // Verification is O(n) - polynomial!
    int sum = 0;
    for (int x : subset) sum += x;
    return sum == target;
}

int main() {
    // P: Binary search runs fast
    vector<int> sorted_arr = {1, 3, 5, 7, 9, 11};
    cout << "Binary Search (P): " << binarySearch(sorted_arr, 7) << endl;

    // NP: We can verify a subset sum answer quickly
    vector<int> arr = {3, 7, 1, 8, -2};
    vector<int> subset = {3, 7, -2};  // certificate/proof
    int target = 8;
    cout << "Subset Sum Verify (NP): " << verifySubsetSum(arr, subset, target) << endl;
    return 0;
}

