#include <iostream>
#include <vector>
using namespace std;

// Demonstrating NP-Complete: Subset Sum (Decision)
// Given a set of integers, is there a subset that sums to target?
// Brute force: O(2^n) - check all subsets
bool subsetSumBruteForce(vector<int>& nums, int target, int idx) {
    if (target == 0) return true;
    if (idx >= nums.size()) return false;
    // Include or exclude current element
    return subsetSumBruteForce(nums, target - nums[idx], idx + 1) ||
           subsetSumBruteForce(nums, target, idx + 1);
}

// Verifier: Given a certificate (subset), verify in O(n)
bool verifySubsetSum(vector<int>& certificate, int target) {
    int sum = 0;
    for (int x : certificate) sum += x;
    return sum == target;
}

int main() {
    vector<int> nums = {3, 34, 4, 12, 5, 2};
    int target = 9;
    cout << "Subset sum exists: " << subsetSumBruteForce(nums, target, 0) << endl;

    // Verification is easy!
    vector<int> certificate = {4, 5};  // 4 + 5 = 9
    cout << "Certificate valid: " << verifySubsetSum(certificate, target) << endl;
    return 0;
}

