from itertools import combinations

# NP-Complete: Subset Sum (Decision)
# Brute force: O(2^n) - check all subsets
def subset_sum_brute(nums, target):
    n = len(nums)
    for r in range(n + 1):
        for combo in combinations(nums, r):
            if sum(combo) == target:
                return True, list(combo)
    return False, []

# Verifier: O(n) - polynomial time
def verify_subset_sum(certificate, target):
    return sum(certificate) == target

# Reduction example: Reducing Subset Sum to 0-1 Knapsack
# If we can solve Knapsack, we can solve Subset Sum
def subset_sum_via_knapsack(nums, target):
    """Reduce Subset Sum -> 0-1 Knapsack
    weights = values = nums, capacity = target
    If max value == target, subset sum exists"""
    n = len(nums)
    dp = [[0] * (target + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for w in range(target + 1):
            dp[i][w] = dp[i-1][w]
            if nums[i-1] <= w:
                dp[i][w] = max(dp[i][w], dp[i-1][w-nums[i-1]] + nums[i-1])
    return dp[n][target] == target

nums = [3, 34, 4, 12, 5, 2]
target = 9
found, cert = subset_sum_brute(nums, target)
print(f"Subset sum exists: {found}, Certificate: {cert}")
print(f"Via reduction to Knapsack: {subset_sum_via_knapsack(nums, target)}")

