#include <iostream>
#include <vector>
#include <set>
using namespace std;

// 2-Approximation for Vertex Cover
vector<int> approxVertexCover(int n, vector<pair<int,int>>& edges) {
    set<int> cover;
    vector<bool> edgeUsed(edges.size(), false);

    for (int i = 0; i < edges.size(); i++) {
        if (!edgeUsed[i]) {
            int u = edges[i].first, v = edges[i].second;
            cover.insert(u);
            cover.insert(v);
            // Remove all edges incident to u or v
            for (int j = i; j < edges.size(); j++) {
                if (edges[j].first == u || edges[j].second == u ||
                    edges[j].first == v || edges[j].second == v)
                    edgeUsed[j] = true;
            }
        }
    }
    return vector<int>(cover.begin(), cover.end());
}

// Greedy TSP (Nearest Neighbor Heuristic)
int greedyTSP(vector<vector<int>>& dist, int n) {
    vector<bool> visited(n, false);
    int curr = 0, totalCost = 0;
    visited[0] = true;

    for (int i = 1; i < n; i++) {
        int nearest = -1, minDist = INT_MAX;
        for (int j = 0; j < n; j++) {
            if (!visited[j] && dist[curr][j] < minDist) {
                minDist = dist[curr][j];
                nearest = j;
            }
        }
        visited[nearest] = true;
        totalCost += minDist;
        curr = nearest;
    }
    totalCost += dist[curr][0]; // Return to start
    return totalCost;
}

int main() {
    // Vertex Cover example
    int n = 5;
    vector<pair<int,int>> edges = {{0,1},{0,2},{1,3},{2,3},{3,4}};
    auto cover = approxVertexCover(n, edges);
    cout << "Vertex Cover: ";
    for (int v : cover) cout << v << " ";
    cout << endl;

    // TSP example
    vector<vector<int>> dist = {
        {0, 10, 15, 20},
        {10, 0, 35, 25},
        {15, 35, 0, 30},
        {20, 25, 30, 0}
    };
    cout << "TSP Greedy Cost: " << greedyTSP(dist, 4) << endl;
    return 0;
}

