import java.util.*;

public class Approximation {
    // 2-Approximation Vertex Cover
    static Set<Integer> approxVertexCover(int n, int[][] edges) {
        Set<Integer> cover = new HashSet<>();
        boolean[] used = new boolean[edges.length];
        for (int i = 0; i < edges.length; i++) {
            if (!used[i]) {
                int u = edges[i][0], v = edges[i][1];
                cover.add(u);
                cover.add(v);
                for (int j = i; j < edges.length; j++) {
                    if (edges[j][0] == u || edges[j][1] == u ||
                        edges[j][0] == v || edges[j][1] == v)
                        used[j] = true;
                }
            }
        }
        return cover;
    }

    // Nearest Neighbor TSP
    static int greedyTSP(int[][] dist) {
        int n = dist.length;
        boolean[] visited = new boolean[n];
        visited[0] = true;
        int curr = 0, total = 0;
        for (int i = 1; i < n; i++) {
            int nearest = -1, minD = Integer.MAX_VALUE;
            for (int j = 0; j < n; j++) {
                if (!visited[j] && dist[curr][j] < minD) {
                    minD = dist[curr][j]; nearest = j;
                }
            }
            visited[nearest] = true;
            total += minD; curr = nearest;
        }
        return total + dist[curr][0];
    }

    public static void main(String[] args) {
        int[][] edges = {{0,1},{0,2},{1,3},{2,3},{3,4}};
        System.out.println("Vertex Cover: " + approxVertexCover(5, edges));
        int[][] dist = {{0,10,15,20},{10,0,35,25},{15,35,0,30},{20,25,30,0}};
        System.out.println("TSP Cost: " + greedyTSP(dist));
    }
}

